        Withdrawal storage withdrawal = withdrawals[withdrawalId];
        require(withdrawal.user != address(0), "INRT: Withdrawal does not exist");
        require(!withdrawal.processed, "INRT: Withdrawal already processed");

        withdrawal.processed = true;
        emit WithdrawalProcessed(withdrawalId);
