    function burnForWithdrawal(address from, uint256 amount, string calldata upiId) external {
        require(owner() == _msgSender() || hookContract == _msgSender(), "INRT: Caller is not owner or authorized hook");
        require(bytes(upiId).length > 0, "INRT: UPI ID cannot be empty");

        // ERC20Burnable's burnFrom handles allowance checks.
        burnFrom(from, amount);

        // Decrease reserves only for withdrawal-related burns, ensuring the 1:1 liability is reduced.
        // solc >0.8.0 provides underflow protection.
        totalBankReserves -= amount;

        _withdrawalCounter++;
        uint256 newWithdrawalId = _withdrawalCounter;

        withdrawals[newWithdrawalId] = Withdrawal({
            user: from,
            amount: amount,
            upiId: upiId,
            timestamp: block.timestamp,
            processed: false
        });

        emit WithdrawalRequested(newWithdrawalId, from, amount, upiId);
        emit TokensBurned(from, amount, newWithdrawalId);
    }

    // --- View Functions ---

    /**
