/**
 * @title CryptoUPIHook
 * @dev A hook contract designed to facilitate UPI withdrawals for INRT tokens.
 * This contract is intended to be the authorized hook in the INRT contract.
 * Users approve this contract to spend their INRT, then call `withdraw` to
 * initiate the burn and withdrawal request process on the main INRT contract.
 */
contract CryptoUPIHook is Ownable {
    IINRT public inrtToken;

    /**
     * @dev Initializes the contract, setting the deployer as the owner.
     */
    constructor() {
        // The Ownable constructor is called implicitly.
    }

    /**
     * @dev Sets the address of the INRT token contract. Can only be called by the owner.
     * @param _inrtToken The address of the INRT contract.
     */
    function setInrtToken(address _inrtToken) public onlyOwner {
        require(_inrtToken != address(0), "CryptoUPIHook: Address cannot be zero");
        inrtToken = IINRT(_inrtToken);
    }

    /**
     * @dev Initiates a withdrawal by calling the INRT contract's `burnForWithdrawal` function.
     * The user calling this function must first approve this contract to spend their INRT tokens.
     * @param amount The amount of INRT to withdraw.
     * @param upiId The user's UPI ID for the off-chain payment.
     */
    function withdraw(uint256 amount, string calldata upiId) external {
        require(address(inrtToken) != address(0), "CryptoUPIHook: INRT token not set");
        inrtToken.burnForWithdrawal(msg.sender, amount, upiId);
    }
